-- Catálogo padrão: toda instalação nova já vem com os formulários 1.1 a 5.1 (os 6.x vêm da V64), com as categorias e as
-- equipes que eles usam. Só acrescenta: formulário cujo código já existe, mesmo excluído, categoria e equipe já cadastradas
-- ficam como estão. Assim uma atualização não desfaz o que o órgão editou nem traz de volta o que ele removeu.

-- Equipes
INSERT INTO itsm.equipe (id, nome, descricao, creator, updater)
SELECT nextval('itsm.equipe_seq'), 'N1 - Service Desk', 'Primeiro atendimento: telefone, portal, e-mail e WhatsApp', '1', '1'
WHERE NOT EXISTS (SELECT 1 FROM itsm.equipe e WHERE e.deleted = 0 AND e.nome = 'N1 - Service Desk');

