SELECT nextval('itsm.formulario_seq'), '1.1', 'Criação de usuário', 'Solicitacao de criacao de novo usuario no Active Directory. Apos aprovacao do superior, o sistema cria login, senha provisoria, copia perfil de referencia e replica grupos.', 'Usuários e acessos', 'fas fa-user-plus', (SELECT c.id FROM itsm.categoria c WHERE c.deleted = 0 AND c.nome_completo = 'Usuários e acessos > Criação de usuário' LIMIT 1), 2, 2, 2, 'Criação de usuário: {nome_completo}',
       '{"secoes": [{"nome": "Dados do colaborador", "perguntas": [{"name": "nome_completo", "type": "text", "label": "Nome completo do colaborador", "regex": null, "values": null, "required": true}, {"name": "data_nascimento", "type": "date", "label": "Data de nascimento (dd/mm/aaaa)", "regex": null, "values": null, "required": true}, {"name": "cpf", "type": "regex", "label": "CPF (11 digitos, somente numeros)", "regex": "/^[0-9]{11}$/", "values": null, "required": true}, {"name": "celular", "type": "regex", "label": "Celular com DDD", "regex": "/^[0-9]{10,11}$/", "values": null, "required": true}, {"name": "matricula", "type": "text", "label": "Matricula funcional", "regex": null, "values": null, "required": true}, {"name": "data_admissao", "type": "date", "label": "Data de admissao (dd/mm/aaaa)", "regex": null, "values": null, "required": true}, {"name": "secretaria", "type": "text", "label": "Secretaria", "regex": null, "values": null, "required": true}, {"name": "coordenadoria", "type": "text", "label": "Coordenadoria", "regex": null, "values": null, "required": true}, {"name": "gerencia", "type": "text", "label": "Gerencia (ou ''Nao se aplica'')", "regex": null, "values": null, "required": false}, {"name": "unidade", "type": "location", "label": "Nome do local/unidade onde trabalhara", "regex": null, "values": null, "required": true}, {"name": "cbo", "type": "text", "label": "CBO/Cargo", "regex": null, "values": null, "required": true}, {"name": "email_pessoal", "type": "email", "label": "E-mail pessoal do colaborador", "regex": null, "values": null, "required": true}, {"name": "email_superior", "type": "email", "label": "E-mail do superior direto (quem vai aprovar)", "regex": null, "values": null, "required": true}]}, {"nome": "Acessos solicitados", "perguntas": [{"name": "usuario_estagiario", "type": "radios", "label": "O colaborador e estagiario?", "regex": null, "values": ["nao", "sim"], "required": true}, {"name": "qual_sistema", "type": "text", "label": "Para qual sistema o acesso sera criado? (ex: Usuario de rede, FAA, PEC, Formsus)", "regex": null, "values": null, "required": true}, {"name": "perfil_referencia", "type": "usuario", "label": "Login de um colega que ja possua o perfil desejado (digite o usuario de rede)", "regex": null, "values": null, "required": true}, {"name": "numero_processo", "type": "text", "label": "Numero do processo 1Doc (opcional, ex: Proc. Administrativo 28.491/2026)", "regex": null, "values": null, "required": false}]}]}',
       'campo', 'email_superior', 'Criar', false, true, 1, '1', '1'
WHERE NOT EXISTS (SELECT 1 FROM itsm.formulario o WHERE o.codigo = '1.1');

